							node_ids: [0, 48],
							data: [null,{type:"data",data:{tool:{name:"Iristick.G2",slug:"Iristick.G2-PRO",shop_url:"https://shop.iristick.com/products/iristick-g2-pro",url:"https://iristick.com/tools/Iristick.G2-PRO/",meta_title:"Iristick.G2 – Certified Smart Safety Glasses | Iristick",meta_description:"Safety-certified smart glasses with central camera, optical zoom and barcode scanner. Capture and share hands-free, in a frame that wears like regular glasses.",label:"",showcase_image_url:"/_app/immutable/assets/g2-side-header-4k.Bbf2BWKm.webp",showcase_seo_image_url:"https://iristick.com/pictures/Iristick.G2.webp",showcase_video_url:"/_app/immutable/assets/website-header-g2-h264.Blab_mEs.mp4",short_description:"Certified smart safety glasses equipped with optimized, central camera with extended field of view, powerful optical zoom and basic barcode scanner for hands-free communication and information sharing. Looks and feels like a regular pair of glasses.",price:"1975",pricing_text:"Our best-selling safety certified smart glasses, designed for daily use. Equipped with a central camera and an additional zoom lens to capture important details.",addtional_info:[{name:"Key Features",tag:"features",topics:[{icon:"camera",title:"Central camera & optical zoom",description:"Capture High-quality images and videos from a natural viewpoint with optical zoom for precise detail.",file:""},{icon:"record_voice_over",title:"Hands-free control",description:" Use the touchpad or voice commands for seamless, hands-free operation.",file:""},{icon:"shield",title:"Robust yet comfortable",description:"These smart safety glasses are designed to endure tough environments while providing all-day comfort.",file:""},{icon:"battery_6_bar",title:"Full-shift battery",description:"The long lasting battery is built to keep you going through a full workday.",file:""},{icon:"fit_screen",title:"Optimized display",description:"See additional information without obstructing your natural field of view.",file:""}]},{name:"Thoughtful Additions",tag:"additions",topics:[{icon:"scale",title:"78 grams",description:"Barely there, fully capable. Experience unparalleled comfort with the Iristick.G2 smart safety glasses, weighing just 78 grams. By offloading processing and battery functions to your smartphone, we've minimized on-head weight and eliminated heat and radiation near your temples. This design ensures all-day wearability without discomfort, allowing you to focus entirely on your tasks.",file:""},{icon:"cable",title:"Smartphone-powered",description:"The Iristick.G2 connects via cable to iOS and Android smartphones, using their cellular and Wi-Fi connectivity while serving as the hub for app installation. This design maximizes performance and battery life by offloading processing to the smartphone. For IT teams, the glasses function as an accessory, seamlessly integrating with existing managed mobile devices.",file:""},{icon:"eyeglasses",title:"Optional inserts for prescription glasses",description:"We offer insert frames for users who wear prescription glasses. These inserts can be fitted with your specific lenses by an optician, allowing multiple users to share the Iristick smart glasses while using their own prescription inserts. This ensures the glasses remain a versatile, shared tool rather than a single-user device.",file:""}]},{name:"Documents",tag:"documents",topics:[{icon:"file_save",title:"spec-sheet-iristick-g2-pro.pdf",description:"",file:"/_app/immutable/assets/spec-sheet-iristick-g2.DRFRI4Ef.pdf"}]}]},faq:[{tool:["Iristick.G2-PRO"],title:"What's in the Box?",description:"The Iristick.G2 package includes smart glasses, a pocket unit (Android or iOS), a battery charger, a USB-C cable, a magnetic plate, and a protective case."},{tool:["Iristick.G2-PRO"],title:"Using the smart glasses",description:"Connect the smart glasses to the pocket unit via the provided coax cable. The pocket unit then connects to your smartphone via USB-C or lightning if it's an older iPhone, utilizing the phone’s processing power for optimal performance."},{tool:["Iristick.G2-PRO"],title:"Charging",description:"Charge the pocket unit with the included charger and cable. A full charge takes approximately 2 hours. Hot-swapping batteries ensures uninterrupted use."},{tool:["Iristick.G2-PRO"],title:"Why is it cabled?",description:"The cable design ensures maximum performance and extended battery life by offloading processing to the smartphone. It also reduces heat, weight and radiation near the temples."},{tool:["Iristick.G2-PRO"],title:"Left eye and right eye compatibility",description:"The 3-axis adjustable display allows for comfortable positioning, making the glasses adaptable to different users. However, the Iristick.G2 work better for right eye dominant people as the HUD is positioned in front of your right eye. "},{tool:["Iristick.G2-PRO"],title:"What if I'm wearing prescription glasses?",description:"The Iristick.G2 is compatible with prescription lenses through insert, ensuring a clear and comfortable user experience."},{tool:["Iristick.G2-PRO"],title:"What if I'm wearing PPE?",description:"Designed to resemble regular glasses, the Iristick.G2 can be comfortably worn alongside other PPE and is a safety certified smart glasses."}]},uses:{params:["slug"]}}],
							form: null,
